function Panel({title,action,children}){return <section style={{background:C.white,border:"1px solid "+C.line,borderRadius:15,padding:16,marginBottom:12,minWidth:0}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:8,flexWrap:"wrap",marginBottom:12}}><h3 style={{fontSize:15,margin:0,fontWeight:850}}>{title}</h3>{action}</div>{children}</section>;}
function Btn({children,onClick,secondary=false,danger=false,disabled=false,type="button"}){return <button type={type} disabled={disabled} onClick={onClick} style={{border:"1px solid "+(danger?"#FECACA":secondary?C.line:C.accent),background:danger?"#FFF1F2":secondary?C.white:C.accent,color:danger?C.red:secondary?C.ink:C.white,borderRadius:9,padding:"9px 12px",fontSize:12,fontWeight:800,cursor:disabled?"not-allowed":"pointer",opacity:disabled ? 0.55 : 1,fontFamily:"inherit"}}>{children}</button>;}
