function Select({label,value,onChange,options}){return <label style={{display:"grid",gap:5,fontSize:11,fontWeight:750,color:C.muted}}>{label}<select value={value} onChange={e=>onChange(e.target.value)} style={{width:"100%",boxSizing:"border-box",border:"1px solid "+C.line,borderRadius:9,padding:"10px 11px",fontSize:13,color:C.ink,background:C.white,fontFamily:"inherit"}}>{options.map(o=>Array.isArray(o)?<option key={o[0]} value={o[0]}>{o[1]}</option>:<option key={o} value={o}>{o}</option>)}</select></label>;}
function Stat({label,value,sub}){return <div style={{border:"1px solid "+C.line,borderRadius:12,padding:14,background:C.white,minWidth:0}}><div style={{fontSize:22,fontWeight:900,color:C.ink,overflowWrap:"anywhere"}}>{value}</div><div style={{fontSize:12,fontWeight:800,marginTop:3}}>{label}</div>{sub&&<div style={{fontSize:10,color:C.muted,marginTop:4}}>{sub}</div>}</div>;}
function Empty({children}){return <div style={{padding:24,textAlign:"center",background:C.bg,borderRadius:11,color:C.muted,fontSize:12}}>{children}</div>;}
function fmt(n){return Number(n||0).toLocaleString("ar-EG",{maximumFractionDigits:1});}
function FoodNutrients({food}){return <div style={{display:"flex",gap:6,flexWrap:"wrap",fontSize:10,color:C.muted,marginTop:7}}>{["calories","proteinG","carbsG","fatG"].map(k=><span key={k} style={{background:C.bg,padding:"4px 6px",borderRadius:6}}>{NUTRIENT_LABELS[k]}: {fmt(food[k])}{k==="calories"?"":""}</span>)}</div>;}

