 const saveBatch=async e=>{e.preventDefault();const recipe=recipes.find(r=>r.id===batchDraft.recipeId);const record={id:uid("batch"),recipeId:batchDraft.recipeId,recipeNameSnapshot:recipe?.name||"",nutrientsPerServingSnapshot:recipe?calculateRecipeNutrition(recipe,rows.recipeIngredients,foods).perServing:null,totalServings:Number(batchDraft.totalServings),consumedServings:0,cookedDate:batchDraft.cookedDate||today,expiryDate:batchDraft.expiryDate||null,notes:batchDraft.notes.trim(),status:"active",createdAt:stamp()};const v=validateCookingBatch(record,recipes);if(!v.ok){fail(v.errors.join(" "));return;}if(await put("batches",record)){setBatchDraft({recipeId:"",totalServings:"4",cookedDate:today,expiryDate:"",notes:""});notify("تم إنشاء دفعة طبخ. لم يتم خصم مكونات أو مخزون Home تلقائيًا.");}};
 const consumeBatch=async batch=>{const remaining=remainingBatchServings(batch);if(remaining<1){fail("لا توجد حصة كاملة متبقية في هذه الدفعة.");return;}const recipe=recipes.find(r=>r.id===batch.recipeId);if(!recipe){fail("الوصفة المرتبطة بالدفعة غير متاحة.");return;}const n=batch.nutrientsPerServingSnapshot||calculateRecipeNutrition(recipe,rows.recipeIngredients,foods).perServing,dateTime=new Date().toISOString(),localDate=nutritionToday(settings.timezone||"Africa/Cairo",new Date(dateTime));const log={id:uid("log"),recipeId:recipe.id,recipeNameSnapshot:batch.recipeNameSnapshot||recipe.name,amount:1,unit:"serving",dateTime,localDate,mealType:"other",notes:"حصة مسجلة من دفعة طبخ "+batch.id,source:"cooking-batch",batchId:batch.id,servingsConsumed:1,nutrientsSnapshot:n,snapshotBasis:"recipe-version-at-batch-consumption",completeness:"complete",createdAt:stamp()};const v=validateFoodLog({recipeId:recipe.id,dateTime,amount:1},foods);if(!v.ok){fail(v.errors.join(" "));return;}if(!await put("logs",log))return;const updated={...batch,consumedServings:Number(batch.consumedServings||0)+1,status:remaining<=1?"depleted":"active",updatedAt:stamp()};if(await put("batches",updated))notify("تم تسجيل حصة في سجل الأكل وتحديث عدد الحصص المتبقية.");};
 const savePlan=async e=>{e.preventDefault();if(!planDraft.date){fail("تاريخ الخطة مطلوب.");return;}const record={id:uid("slot"),date:planDraft.date,mealType:planDraft.mealType,recipeId:planDraft.recipeId||null,portions:Math.max(1,Number(planDraft.portions)||1),notes:planDraft.notes.trim(),status:"planned",confirmed:false,createdAt:stamp()};if(await put("planSlots",record)){try{publishOSEvent({type:"nutrition.plan.slot.created",entityType:"nutrition-plan-slot",entityId:record.id,payload:{date:record.date,mealType:record.mealType,recipeId:record.recipeId,portions:record.portions}},ws?.id||api?.workspaceId||"default","nutrition");}catch{}const ref=buildNutritionCalendarReference(ws?.id||api?.workspaceId||"default",record,recipes.find(r=>r.id===record.recipeId));if(ref&&nutritionIntegrations.items.find(x=>x.id==="calendar")?.available)await nutritionBridge.upsertCalendarEvent(ref);setPlanDraft(p=>({...p,recipeId:"",notes:""}));notify("أُضيف الاقتراح للخطة؛ لا يُسجّل كوجبة فعلية حتى تسجله في سجل الأكل.");}};
 const saveGrocery=async e=>{e.preventDefault();if(!groceryName.trim()){fail("اسم البند مطلوب.");return;}await put("groceryItems",{id:uid("grocery"),name:groceryName.trim(),amount:Number(groceryAmount)||null,unit:groceryUnit,status:"needed",source:"manual",createdAt:stamp()});setGroceryName("");setGroceryAmount("");};
 const saveSupplement=async e=>{e.preventDefault();if(!supplementDraft.name.trim()){fail("اسم المكمل مطلوب.");return;}await put("supplements",{id:uid("supp"),...supplementDraft,name:supplementDraft.name.trim(),status:"active",createdAt:stamp()});setSupplementDraft({name:"",brand:"",dose:"",unit:"",schedule:"",notes:""});};
 const saveWindow=async e=>{e.preventDefault();if(!windowDraft.name.trim()){fail("اسم النافذة مطلوب.");return;}if(windowDraft.startTime&&windowDraft.endTime&&windowDraft.startTime===windowDraft.endTime){fail("وقت البداية والنهاية لا يمكن أن يتطابقا.");return;}await put("windows",{id:uid("window"),...windowDraft,enabled:!!windowDraft.enabled,createdAt:stamp()});setWindowDraft({name:"",startTime:"",endTime:"",days:"كل الأيام",enabled:true});};
 const exportJson=()=>{const payload={...emptyNutritionData(),schemaVersion:1};for(const key of Object.keys(payload))if(Array.isArray(payload[key]))payload[key]=rows[key]||[];const blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="nutrition-os-export.json";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify("تم تجهيز ملف التصدير.");};
 const importJson=async()=>{try{const parsed=JSON.parse(importText),v=validateNutritionImport(parsed);if(!v.ok){fail(v.errors.slice(0,5).join(" "));return;}if(!window.confirm("سيتم استيراد "+Object.values(v.data).filter(Array.isArray).reduce((n,a)=>n+a.length,0)+" سجلًا. الاستيراد يضيف السجلات الجديدة ولا يحذف البيانات الحالية. متابعة؟"))return;let count=0;for(const coll of Object.keys(v.data)){if(!Array.isArray(v.data[coll]))continue;for(const row of v.data[coll]){if(rows[coll]?.some(x=>x.id===row.id))continue;await store.api.put(coll,row);count++;}}notify("اكتمل استيراد "+count+" سجلًا جديدًا.");}catch(e){fail("تعذرت قراءة JSON: "+(e?.message||"صيغة غير صالحة"));}};
 const makeGroceryFromPlan=async()=>{const needs=buildGroceryNeeds({planSlots:rows.planSlots,recipes:rows.recipes,recipeIngredients:rows.recipeIngredients,foods:rows.foods});if(!needs.length){notify("لا توجد مكونات مرتبطة بوصفات نشطة في الخطة.");return;}let added=0,merged=0,skipped=0;for(const need of needs){const existing=rows.groceryItems.find(g=>g.status!=="archived"&&g.foodId===need.foodId&&String(g.unit||"")===String(need.unit||"")&&g.status!=="purchased");if(!existing){await store.api.put("groceryItems",{id:uid("grocery"),...need,status:"needed",source:"meal-plan",createdAt:stamp()});added++;continue;}const seen=new Set(existing.sourceSlotIds||[]),fresh=(need.sourceSlotIds||[]).filter(id=>!seen.has(id));if(!fresh.length){skipped++;continue;}const delta=fresh.reduce((sum,id)=>sum+Number(need.sourceSlotAmounts?.[id]||0),0);await store.api.put("groceryItems",{...existing,amount:Math.round((Number(existing.amount||0)+delta)*100)/100,sourceSlotIds:[...seen,...fresh],sourceSlotAmounts:{...(existing.sourceSlotAmounts||{}),...Object.fromEntries(fresh.map(id=>[id,need.sourceSlotAmounts[id]]))},updatedAt:stamp()});merged++;}notify("قائمة البقالة: "+added+" بند جديد، "+merged+" تحديث، "+skipped+" بلا تغيير (منعًا للتكرار).");};
